import '../styles.css';
import {createViewer} from './viewer.js';
import {getModel,getCatalog,SYSTEMS,SYSTEM_LABELS,SOURCE_CREDIT,SOURCE_LINK,SOURCE_LICENSE_LINK} from './model.js';
import {displayLabel} from './labels.js';

const COPY={nl:{brand:'3D Universe',preview:'Technische ontwikkelpreview',pageTitle:'Ontdek het menselijk lichaam',intro:'Verken de echte anatomische brongeometrie per systeem en structuur.',modelLabel:'Lichaamsmodel',modelMale:'Mannelijk referentiemodel',modelFemale:'Vrouwelijk referentiemodel',localeLabel:'Taal',modeLabel:'Informatiewijze',modeHerstellen:'Herstellen',modeTrainen:'Trainen',modeLeren:'Leren',modeBlessures:'Blessures',modeSporten:'Sporten',structuresTitle:'Anatomie',searchLabel:'Zoeken in de catalogus',searchPlaceholder:'Zoek spieren, organen, botten…',layersTitle:'Lichaamssystemen',catalogTitle:'Structuren',viewerTitle:'3D-atlas',viewerHint:'Sleep om te draaien · scroll of knijp om te zoomen',detailTitle:'Structuurinformatie',focus:'Focus',isolate:'Isoleer',reset:'Reset',clear:'Deselecteer',sourcesTitle:'Herkomst en licentie',sourcesIntro:'Bronmateriaal en de grenzen van deze proefopstelling.',technicalTitle:'Technische gegevens',technicalIntro:'Gemeten tijdens deze browsersessie.',previewDisclaimer:'Technische test, geen complete anatomie-atlas. Geometrie, vertalingen en medische inhoud vereisen onafhankelijke inhoudelijke review.',skipLink:'Naar structuurgegevens',footer:'3D Universe · Educatieve ontwikkelpreview',ready:'3D-model geladen',loading:'Anatomisch model laden…',error:'3D-weergave niet beschikbaar; gebruik de structuurlijst.',noSelection:'Selecteer een structuur',noSelectionDetail:'Kies een zichtbaar onderdeel in de 3D-weergave of zoek in de volledige broncatalogus.',sourceLabel:'Bronlabel',mesh:'Bronmesh',hotspot:'Gewrichtsanker (geen afzonderlijke mesh)',noResults:'Geen overeenkomende structuren.',draft:'Voorlopige vertaling en bronmetadata. Nog niet anatomisch gereviewd.',showAll:'Toon alle lagen',hideAll:'Verberg alle lagen',restore:'Stop isolatie',modePending:'Uitgewerkte, gereviewde uitleg voor deze modus is nog niet beschikbaar. De selectie en broninformatie blijven wel behouden.',structures:'structuren',mapped:'Gekoppeld',hotspots:'ankers',triangles:'driehoeken (render)',calls:'rendercalls',notMeasured:'Nog geen rendermeting',creditsLink:'Bronrepository',licenseLink:'CC BY 4.0-licentie',unmapped:'Niet gekoppelde bronrecords',contextLost:'GPU-context verloren; de catalogus blijft beschikbaar.',selected:'Geselecteerd',groupNote:'Een bronrecord kan meerdere anatomische onderdelen groeperen; afzonderlijke einddekking vereist verdere validatie.'},
en:{brand:'3D Universe',preview:'Technical development preview',pageTitle:'Explore the human body',intro:'Explore actual reference geometry by system and structure.',modelLabel:'Body model',modelMale:'Male reference model',modelFemale:'Female reference model',localeLabel:'Language',modeLabel:'Learning perspective',modeHerstellen:'Recovery',modeTrainen:'Training',modeLeren:'Learn',modeBlessures:'Injuries',modeSporten:'Sports',structuresTitle:'Anatomy',searchLabel:'Search the catalog',searchPlaceholder:'Search muscles, organs, bones…',layersTitle:'Body systems',catalogTitle:'Structures',viewerTitle:'3D atlas',viewerHint:'Drag to rotate · scroll or pinch to zoom',detailTitle:'Structure information',focus:'Focus',isolate:'Isolate',reset:'Reset',clear:'Clear selection',sourcesTitle:'Provenance and license',sourcesIntro:'Source material and limitations of this prototype.',technicalTitle:'Technical information',technicalIntro:'Measured during this browser session.',previewDisclaimer:'Technical test, not a complete anatomy atlas. Geometry, translations and medical content require independent scientific review.',skipLink:'Skip to structure details',footer:'3D Universe · Educational development preview',ready:'3D model loaded',loading:'Loading anatomical model…',error:'3D view unavailable; use the structure list.',noSelection:'Select a structure',noSelectionDetail:'Choose a visible part of the 3D view or search the complete source catalog.',sourceLabel:'Source label',mesh:'Source mesh',hotspot:'Joint anchor (not a separate mesh)',noResults:'No matching structures.',draft:'Draft translation and source metadata. Not yet anatomically reviewed.',showAll:'Show all layers',hideAll:'Hide all layers',restore:'Stop isolation',modePending:'Reviewed educational content for this mode is not available yet. The selection and source information are preserved.',structures:'structures',mapped:'Mapped',hotspots:'anchors',triangles:'triangles (render)',calls:'draw calls',notMeasured:'No render measurement yet',creditsLink:'Source repository',licenseLink:'CC BY 4.0 license',unmapped:'Unmapped source records',contextLost:'GPU context lost; the catalog remains available.',selected:'Selected',groupNote:'One source record may group several anatomical parts; individual final coverage requires further validation.'}};

const $=id=>document.getElementById(id);
const state={locale:'nl',variant:'male',mode:'leren',catalog:[],selected:null,isolated:null,visible:new Set(['skeleton','muscles','organs','vessels','nerves','joints']),phase:'idle',viewerAvailable:false,token:0,metrics:null};
const t=key=>COPY[state.locale][key]??key;
let viewer=null, errorDetail='';

function setPhase(phase){state.phase=phase;const el=$('status');el.dataset.phase=phase;el.textContent=t(phase==='ready'?'ready':phase==='loading'?'loading':phase==='context-lost'?'contextLost':phase==='error'?'error':'loading');}
function setError(message=''){errorDetail=message;const el=$('error');el.hidden=!message;el.textContent=message?`${t('error')} ${message}`:'';}
function showMetrics(metrics=state.metrics){
  if(!metrics){$('metrics').textContent=t('notMeasured');return;}
  state.metrics=metrics;const format=n=>typeof n==='number'?n.toLocaleString(state.locale):'—';
  const mapped=Array.isArray(metrics.mappedKeys)?metrics.mappedKeys.length:metrics.mappedKeys;
  const joints=Array.isArray(metrics.hotspotKeys)?metrics.hotspotKeys.length:metrics.hotspotKeys;
  const missing=Array.isArray(metrics.missingKeys)?metrics.missingKeys.length:metrics.missingKeys;
  $('metrics').textContent=`${t('mapped')}: ${format(mapped)} · ${t('hotspots')}: ${format(joints)} · ${t('triangles')}: ${format(metrics.triangles)} · ${t('calls')}: ${format(metrics.calls)} · ${t('unmapped')}: ${format(missing)}`;
}

function renderTranslation(){document.documentElement.lang=state.locale;for(const el of document.querySelectorAll('[data-i18n]')){const key=el.dataset.i18n;if(COPY[state.locale][key])el.textContent=t(key);}for(const el of document.querySelectorAll('[data-i18n-placeholder]'))el.placeholder=t(el.dataset.i18nPlaceholder);setPhase(state.phase);setError(errorDetail);renderLayers();renderList();renderDetail();renderCredits();showMetrics();}
function renderCredits(){const el=$('credits');el.replaceChildren();const p=document.createElement('p');p.textContent=SOURCE_CREDIT;el.append(p);for(const [url,label] of [[SOURCE_LINK,t('creditsLink')],[SOURCE_LICENSE_LINK,t('licenseLink')]]){if(typeof url!=='string')continue;const a=document.createElement('a');a.href=url;a.textContent=label;a.target='_blank';a.rel='noopener noreferrer';el.append(a,document.createTextNode('  '));}}

function updateVisibility(){viewer?.setVisibleSystems(new Set(state.visible));renderLayers();updateControls();}
function renderLayers(){const el=$('layers'),focused=el.contains(document.activeElement)?document.activeElement.dataset.system:null;el.replaceChildren();for(const system of SYSTEMS){const label=document.createElement('label');label.className='layer-row';const input=document.createElement('input');input.type='checkbox';input.checked=state.visible.has(system);input.dataset.system=system;input.setAttribute('aria-label',SYSTEM_LABELS[state.locale][system]);input.addEventListener('change',()=>{if(input.checked)state.visible.add(system);else state.visible.delete(system);updateVisibility();});const name=document.createElement('span');name.textContent=SYSTEM_LABELS[state.locale][system];const count=document.createElement('small');count.textContent=state.catalog.filter(x=>x.system===system).length;label.append(input,name,count);el.append(label);if(system===focused)input.focus({preventScroll:true});}}

function renderList(){const el=$('structure-list'),q=$('search').value.toLocaleLowerCase(state.locale).trim();el.replaceChildren();const matches=state.catalog.filter(x=>!q||[displayLabel(x,state.locale),x.label,x.key,SYSTEM_LABELS[state.locale][x.system]].some(s=>String(s).toLocaleLowerCase(state.locale).includes(q)));$('structure-count').textContent=`${matches.length} / ${state.catalog.length} ${t('structures')}`;
  if(!matches.length){const p=document.createElement('p');p.textContent=t('noResults');el.append(p);return;}
  for(const system of SYSTEMS){const items=matches.filter(x=>x.system===system);if(!items.length)continue;const group=document.createElement('section');group.className='structure-group';const title=document.createElement('h3');title.textContent=SYSTEM_LABELS[state.locale][system];group.append(title);for(const item of items){const button=document.createElement('button');button.type='button';button.className='structure-item';button.dataset.key=item.key;button.setAttribute('aria-pressed',String(state.selected===item.key));const title=document.createElement('span');title.textContent=displayLabel(item,state.locale);const sub=document.createElement('small');sub.textContent=item.key;button.append(title,sub);button.addEventListener('click',()=>choose(item.key,true));group.append(button);}el.append(group);}}

function renderDetail(){const item=state.catalog.find(x=>x.key===state.selected);$('detail-title').textContent=item?displayLabel(item,state.locale):t('noSelection');$('detail-meta').textContent=item?`${SYSTEM_LABELS[state.locale][item.system]} · ${item.system==='joints'?t('hotspot'):t('mesh')}`:'';const el=$('detail-content');el.replaceChildren();
  if(!item){const p=document.createElement('p');p.textContent=t('noSelectionDetail');el.append(p);}else{const dl=document.createElement('dl');const dt=document.createElement('dt');dt.textContent=t('sourceLabel');const dd=document.createElement('dd');dd.textContent=item.label;const key=document.createElement('dt');key.textContent='ID';const value=document.createElement('dd');value.textContent=item.key;dl.append(dt,dd,key,value);const draft=document.createElement('p');draft.className='detail-notice';draft.textContent=t('draft');const notice=document.createElement('p');notice.textContent=t('groupNote');const mode=document.createElement('p');mode.textContent=t('modePending');el.append(dl,draft,notice,mode);}
  updateControls();}
function updateControls(){const has=Boolean(state.selected),ready=state.phase==='ready'&&state.viewerAvailable;$('focus-btn').disabled=!has||!ready;$('isolate-btn').disabled=!has||!ready;$('reset-btn').disabled=!ready;$('clear-btn').disabled=!has;$('isolate-btn').setAttribute('aria-pressed',String(Boolean(state.isolated)));$('isolate-btn').textContent=t(state.isolated?'restore':'isolate');}
function selectFromViewer(key){if(key!==null&&!state.catalog.some(x=>x.key===key))return;state.selected=key;for(const el of $('structure-list').querySelectorAll('[data-key]'))el.setAttribute('aria-pressed',String(el.dataset.key===key));renderDetail();}
function choose(key,focus=false){const item=state.catalog.find(x=>x.key===key);if(!item)return;if(state.isolated&&state.isolated!==key){viewer?.isolate(null);state.isolated=null;}if(!state.visible.has(item.system)){state.visible.add(item.system);updateVisibility();}selectFromViewer(key);if(state.phase==='ready'){try{viewer?.select(key,{focus});}catch(e){setError(e.message);}}}

async function loadVariant(variant){const ticket=++state.token,previous=state.selected;state.variant=variant;state.catalog=getCatalog(variant);state.selected=state.catalog.some(x=>x.key===previous)?previous:null;state.isolated=null;state.metrics=null;setError();renderLayers();renderList();renderDetail();showMetrics();setPhase('loading');updateControls();
  if(!viewer){setPhase('error');setError('WebGL2');updateControls();return;}
  try{const metrics=await viewer.load(getModel(variant));if(ticket!==state.token)return;state.viewerAvailable=true;viewer.setVisibleSystems(new Set(state.visible));const key=state.selected??(state.catalog.some(x=>x.key===previous)?previous:null);if(key){selectFromViewer(key);viewer.select(key,{focus:false});}setPhase(metrics.ready?'ready':'context-lost');showMetrics(metrics);updateControls();}
  catch(e){if(ticket!==state.token)return;state.viewerAvailable=false;setPhase('error');setError(e?.message??String(e));updateControls();}}

try{viewer=createViewer($('viewport'),{onSelect:key=>{if(state.phase!=='loading')selectFromViewer(key);},onStatus:s=>{if(s.phase==='loading'||s.phase==='context-lost'||s.phase==='error'||s.phase==='ready'){setPhase(s.phase);updateControls();}if(s.metrics)showMetrics(s.metrics);},onError:e=>{setError(e?.message??String(e));}});}catch(e){setError(e?.message??'WebGL2');}
$('locale-select').addEventListener('change',e=>{state.locale=e.target.value==='en'?'en':'nl';renderTranslation();});
$('model-select').addEventListener('change',e=>{loadVariant(e.target.value);});
$('mode-select').addEventListener('change',e=>{state.mode=e.target.value;renderDetail();});
$('search').addEventListener('input',renderList);
$('focus-btn').addEventListener('click',()=>{if(state.selected){const item=state.catalog.find(x=>x.key===state.selected);if(item&&!state.visible.has(item.system)){state.visible.add(item.system);updateVisibility();}viewer?.focus(state.selected);}});
$('isolate-btn').addEventListener('click',()=>{if(!state.selected)return;const item=state.catalog.find(x=>x.key===state.selected);if(!state.isolated&&item&&!state.visible.has(item.system)){state.visible.add(item.system);updateVisibility();}state.isolated=state.isolated?null:state.selected;viewer?.isolate(state.isolated);updateControls();});
$('reset-btn').addEventListener('click',()=>{state.isolated=null;viewer?.reset();selectFromViewer(null);updateControls();});
$('clear-btn').addEventListener('click',()=>{if(state.isolated){viewer?.isolate(null);state.isolated=null;}viewer?.select(null);selectFromViewer(null);});
const mobile=$('mobile-structures-btn');if(mobile)mobile.addEventListener('click',()=>{const panel=$('nav-panel');const collapsed=panel.classList.toggle('mobile-collapsed');mobile.setAttribute('aria-expanded',String(!collapsed));});
window.addEventListener('pagehide',e=>{if(!e.persisted)viewer?.dispose();});
renderTranslation();loadVariant(state.variant);
const timer=setInterval(()=>{if(state.phase==='ready'&&viewer)showMetrics(viewer.getMetrics());},2000);window.addEventListener('pagehide',e=>{if(!e.persisted)clearInterval(timer);});
